{"code": "
import sys

def is_lucky(sub):
    """Check if a substring is a lucky number"""
    return all(c in {'4', '7'} for c in sub)

def solve(s):
    """Find the lucky substring with maximum occurrences and lexicographically smallest"""
    # Dictionary to count occurrences of each lucky substring
    count = {}

    # Generate all possible substrings
    n = len(s)
    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            if substr[0] == '0':  # Skip substrings with leading zeroes
                continue
            if is_lucky(substr):
                count[substr] = count.get(substr, 0) + 1

    if not count:
        return "-1"

    # Find the substring with maximum occurrences
    max_count = max(count.values())
    candidates = [k for k, v in count.items() if v == max_count]

    # Return the lexicographically smallest candidate
    return min(candidates)

def main():
    s = sys.stdin.read().strip()
    result = solve(s)
    print(result)

if __name__ == "__main__":
    main()
"}

