import sys

def min_digit(x):
    return min(int(d) for d in str(x))

def max_digit(x):
    return max(int(d) for d in str(x))

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        a1 = int(data[idx])
        K = int(data[idx + 1])
        idx += 2

        current = a1
        for _ in range(K - 1):
            min_d = min_digit(current)
            max_d = max_digit(current)
            increment = min_d * max_d

            if increment == 0:
                break  # Sequence becomes constant

            current += increment

        print(current)

if __name__ == "__main__":
    solve()
"}

