def count_good_pairs(l, r, x, y):
    """Count good pairs (a, b) such that GCD(a, b) = x and LCM(a, b) = y"""
    if y % x != 0:
        return 0

    target = y // x

    # Find all pairs (a', b') such that a' * b' = target and GCD(a', b') = 1
    # Since a' and b' are coprime, they must be divisors of target
    # and their product must be target

    count = 0

    # Find all divisors of target
    divisors = set()
    for i in range(1, int(target**0.5) + 1):
        if target % i == 0:
            divisors.add(i)
            divisors.add(target // i)

    # Check each divisor pair
    for a_prime in divisors:
        b_prime = target // a_prime

        # Check if GCD(a_prime, b_prime) == 1
        if math.gcd(a_prime, b_prime) == 1:
            a = x * a_prime
            b = x * b_prime

            # Check if both are within [l, r]
            if l <= a <= r and l <= b <= r:
                count += 1

    return count

def solve():
    l, r, x, y = map(int, input().split())
    print(count_good_pairs(l, r, x, y))

if __name__ == "__main__":
    solve()
"}

