import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return

    # Parse input
    line = data[0].split()
    n, m = int(line[0]), int(line[1])

    # Read names
    names = []
    for i in range(1, n + 1):
        names.append(data[i])

    # Create compatibility matrix
    compat = [[True] * n for _ in range(n)]

    # Read incompatible pairs
    for i in range(n, n + m):
        a, b = data[i].split()
        a_idx = names.index(a)
        b_idx = names.index(b)
        compat[a_idx][b_idx] = False
        compat[b_idx][a_idx] = False

    # Find maximum clique
    for size in range(n, 0, -1):
        for mask in range(1 << n):
            if bin(mask).count('1') != size:
                continue

            # Check if this subset is compatible
            valid = True
            for i in range(n):
                if (mask & (1 << i)) == 0:
                    continue
                for j in range(i + 1, n):
                    if (mask & (1 << j)) == 0:
                        continue
                    if not compat[i][j]:
                        valid = False
                        break
                if not valid:
                    break

            if valid:
                # Output result
                subset = [names[i] for i in range(n) if (mask & (1 << i))]
                subset.sort()
                print(len(subset))
                for name in subset:
                    print(name)
                return

    # Shouldn't reach here
    print(1)
    print(names[0])

if __name__ == "__main__":
    solve()
