def largest_square_divisor(d):
    """Find the largest square divisor of d."""
    # Factorize d
    factors = {}
    temp = d

    # Check for 2
    while temp % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        temp //= 2

    # Check for odd primes
    i = 3
    while i * i <= temp:
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
        i += 2

    if temp > 1:
        factors[temp] = 1

    # Calculate the largest square divisor
    square_divisor = 1
    for prime, exp in factors.items():
        square_divisor *= prime ** (exp // 2)

    return square_divisor

def solve():
    a, n = map(int, input().split())

    result = 0
    for d in range(a, a + n):
        s2 = largest_square_divisor(d)
        result += d // s2

    print(result)

solve()
