def largest_square_divisor(d):
    """Find the largest square divisor of d (not 1)."""
    # Factorize d
    factors = {}
    temp = d

    # Check for 2
    if temp % 2 == 0:
        cnt = 0
        while temp % 2 == 0:
            temp //= 2
            cnt += 1
        if cnt > 0:
            factors[2] = cnt

    # Check for odd primes
    i = 3
    while i * i <= temp:
        if temp % i == 0:
            cnt = 0
            while temp % i == 0:
                temp //= i
                cnt += 1
            if cnt > 0:
                factors[i] = cnt
        i += 2

    if temp > 1:
        # temp is prime
        cnt = 1
        if cnt > 0:
            factors[temp] = cnt

    # Build the largest square divisor
    square_divisor = 1
    if 1 in factors:
        del factors[1]
    for prime, exp in factors.items():
        square_divisor *= prime ** (exp // 2 * 2)

    return square_divisor

def solve():
    a, n = map(int, input().split())
    result = 0
    for d in range(a, a + n):
        s2 = largest_square_divisor(d)
        result += d // s2
    print(result)

solve()

