    print("YES")

    for i in range(n):
        if i % 2 == 0:
            # Even index: (b, g) where b = i//2 % k + 1, g = b + 1 (mod k)
            b = (i // 2) % k + 1
            g = b + 1 if b + 1 <= k else 1
        else:
            # Odd index: (g, b) where g = i//2 % k + 1, b = g + 1 (mod k)
            g = (i // 2) % k + 1
            b = g + 1 if g + 1 <= k else 1

        print(b, g)

