def solve():
    import sys
    input = sys.stdin.read().split()

    if not input:
        return

    n = int(input[0])
    m = int(input[1])

    grid = []
    idx = 2
    for i in range(n):
        grid.append(input[idx])
        idx += 1

    # Find connected components of '.' cells
    visited = [[False] * m for _ in range(n)]
    component_sizes = []
    component_id = [[-1] * m for _ in range(n)]

    dir = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find component
                from collections import deque
                q = deque([(i, j)])
                visited[i][j] = True
                component_id[i][j] = len(component_sizes)
                size = 1

                while q:
                    x, y = q.popleft()
                    for dx, dy in dir:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                            visited[nx][ny] = True
                            component_id[nx][ny] = len(component_sizes)
                            size += 1
                            q.append((nx, ny))

                component_sizes.append(size)

    # Build answer matrix
    result = [[''] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                result[i][j] = '.'
            else:
                # '*' cell, check neighbors
                total = 1  # include itself
                for dx, dy in dir:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
                        total += component_sizes[component_id[nx][ny]]

