def is_valid_coloring(n, edges, colors):
    """Check if the coloring is valid"""
    # Create adjacency set
    adj = [set() for _ in range(n)]
    for u, v in edges:
        adj[u-1].add(v-1)
        adj[v-1].add(u-1)

    # Check all pairs
    for i in range(n):
        for j in range(i+1, n):
            # Check if i and j are adjacent
            adjacent = j in adj[i]

            # Get colors
            ci = colors[i]
            cj = colors[j]

            # Check if they are neighboring or equal
            if adjacent:
                if ci != cj and abs(ord(ci) - ord(cj)) != 1:
                    return False
            else:
                if ci == cj or abs(ord(ci) - ord(cj)) == 1:
                    return False
    return True

def solve():
