import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    # Check if it's impossible
    if n > k * (k - 1):
        print("NO")
        return

    # Use a pattern that cycles through valid pairs
    # Pattern: (i % k + 1, i % k + 2) if i % k + 2 <= k, else (i % k + 2, i % k + 1)
    print("YES")
    for i in range(n):
        if i % k + 2 <= k:
            b = i % k + 1
            g = i % k + 2
        else:
            b = i % k + 2
            g = i % k + 1

        # Ensure no consecutive pairs have the same color in both positions
        if i > 0:
            prev_b, prev_g = (i-1) % k + 1, (i-1) % k + 2
            if (i-1) % k + 2 > k:
                prev_b, prev_g = (i-1) % k + 2, (i-1) % k + 1

            # Check if consecutive pairs differ in both colors
            if b == prev_b or g == prev_g:
                # Adjust by swapping colors if needed
                b, g = g, b

        print(f"{b} {g}")

if __name__ == "__main__":
