import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count frequency of each value
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Sort values in decreasing order
    values = sorted(freq.keys(), reverse=True)

    # Track which values we've deleted
    deleted = set()

    total_points = 0

    for v in values:
        if v in deleted:
            continue

        # Calculate points for deleting v
        points = v * freq[v]

        # Check if v-1 exists and hasn't been deleted
        if (v - 1) in freq and (v - 1) not in deleted:
            points -= freq[v - 1]

        # Check if v+1 exists and hasn't been deleted
        if (v + 1) in freq and (v + 1) not in deleted:
            points -= freq[v + 1]

        total_points += points

        # Mark v, v-1, and v+1 as deleted
        deleted.add(v)
        if (v - 1) in freq:
            deleted.add(v - 1)
        if (v + 1) in freq:
            deleted.add(v + 1)

    print(total_points)

if __name__ == "__main__":
    solve()
