def solve():
    a, n = map(int, input().split())

    # Maximum possible year
    max_year = a + n - 1

    # Precompute smallest prime factor (SPF) for each number up to max_year
    max_spf = max_year
    spf = list(range(max_spf + 1))  # spf[i] is the smallest prime factor of i

    for i in range(2, int(max_spf**0.5) + 1):
        if spf[i] == i:  # i is prime
            for j in range(i * i, max_spf + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def get_prime_factors(x):
        """Return the prime factorization of x as a dictionary"""
        factors = {}
        while x > 1:
            p = spf[x]
            count = 0
            while x % p == 0:
                x //= p
                count += 1
            factors[p] = count
        return factors

    def largest_square_divisor(D):
        """Find the largest square divisor of D"""
        factors = get_prime_factors(D)
        square = 1
        for p, cnt in factors.items():
            square *= p ** (cnt // 2)
        return square

    total = 0
    for year in range(a, a + n):
        D = year
        s2 = largest_square_divisor(D)
        total += D // s2

    print(total)

solve()
