    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    k = int(next(it))

    # Read initial state
    state = next(it)

    # Read subsets
    subsets = [[] for _ in range(n)]

    for sub_idx in range(k):
        # Read the number of elements in this subset
        c = int(next(it))

        # Read the elements
        for _ in range(c):
            x = int(next(it)) - 1  # Convert to 0-indexed
            subsets[x].append(sub_idx)  # Record which subset it belongs to

    # Verify
    print("subsets:", subsets)

    # For each lamp from 1 to n (0-indexed), we'll track the current state
    current_state = [int(c) for c in state]

    applied = [False] * k

    result = []

    for i in range(n):
        if all(current_state[0:i+1]):
            result.append(len(result))
        else:
            # Find the rightmost lamp that is off
            for j in range(i, -1, -1):
                if not current_state[j]:
                    # Find a subset that contains lamp j
                    if not subsets[j]:
                        print(f"Error: Lamp {j+1} has no subsets!")
