                    # Check if other piece is on the same diagonal
                    if abs(other_x - x) == abs(other_y - y):
                        # Check if other piece is between the current piece and the king
                        dist_current_to_other = abs(other_x - x) + abs(other_y - y)
                        dist_current_to_king = abs(king_x - x) + abs(king_y - y)

