def can_interleave(x, y):
    """Check if we can interleave x and y such that no two consecutive characters are the same."""
    if not x and not y:
        return 0
    if not x:
        return 1 if len(set(y)) == len(y) else 0
    if not y:
        return 1 if len(set(x)) == len(x) else 0

    # Check if we can interleave starting with x
    def check_start_with_x(x, y):
        if not x or not y:
            return 1
        if x[0] == y[0]:
            return 0
        return check_start_with_x(x[1:], y[1:])

    # Check if we can interleave starting with y
    def check_start_with_y(x, y):
        if not x or not y:
            return 1
        if x[0] == y[0]:
            return 0
        return check_start_with_y(x[1:], y[1:])

    # We can start with x or y
    return check_start_with_x(x, y) + check_start_with_y(x, y)

