from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    grid = []
    idx = 2

    for i in range(n):
        row = []
        for j in range(m):
            row.append(data[idx])
            idx += 1
        grid.append(row)

    # Find connected components of '.' cells
    visited = [[False] * m for _ in range(n)]
    components = []

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and not visited[i][j]:
                # BFS to find the component
                queue = deque([(i, j)])
                visited[i][j] = True
                component = [(i, j)]

                while queue:
                    x, y = queue.popleft()
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and not visited[nx][ny]:
                                visited[nx][ny] = True
                                queue.append((nx, ny))
                                component.append((nx, ny))

                components.append(component)

    # Build answer matrix
    answer = [['.' for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
