import sys
from itertools import permutations

def is_strictly_greater(s, t):
    """Check if string s is lexicographically strictly greater than t"""
    min_len = min(len(s), len(t))
    for i in range(min_len):
        if s[i] < t[i]:
            return True
        elif s[i] > t[i]:
            return False
    # If all min_len characters are equal
    if len(s) > len(t):
        return True
    elif len(s) < len(t):
        return False
    else:
        return False  # lengths are equal and all characters are equal

def solve():
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    # Generate all permutations of s
    chars = list(s)
    perms = permutations(chars)

    # Check each permutation in lexicographical order
    for perm in perms:
        perm_str = ''.join(perm)
        if is_strictly_greater(perm_str, t):
            print(perm_str)
            return

    print(-1)

if __name__ == "__main__":
    solve()
