    number = "1" + "0" * (n - 1)

    # If this number is divisible by t, use it
    if int(number) % t == 0:
        print(number)
    else:
        # Find the smallest n-digit number divisible by t
        # Start from 10^(n-1) and find the next multiple of t
        start = 10 ** (n - 1)
        # Find the smallest number >= start that is divisible by t
        # We can add (t - start % t) to start, but need to handle start % t == 0
        if start % t == 0:
            print(number)
        else:
            result = start + (t - start % t)
            result_str = str(result)

            # Ensure the result has exactly n digits
            # If result has fewer than n digits, it means start % t + t > 10^n - 1
            # This should never happen for n >= 2
