import sys

def is_lucky(sub):
    """Check if a substring is a lucky number"""
    if sub[0] == '0':
        return False  # No leading zeroes
    for ch in sub:
        if ch not in {'4', '7'}:
            return False
    return True

def solve(s):
    """Find the lucky substring that appears most frequently and is lexicographically smallest"""
    substrings = set()

    # Generate all non-empty substrings
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            substrings.add(s[i:j])

    # Filter lucky numbers
    lucky_numbers = [sub for sub in substrings if is_lucky(sub)]

    if not lucky_numbers:
        return -1

    # Count frequencies
    freq = {}
    for sub in lucky_numbers:
        freq[sub] = freq.get(sub, 0) + 1

    # Find maximum frequency
    max_freq = max(freq.values())

    # Find all substrings with max frequency
    candidates = [sub for sub, count in freq.items() if count == max_freq]

    # Return lexicographically smallest
    return min(candidates)

if __name__ == "__main__":
    s = sys.stdin.readline().strip()
    result = solve(s)
    print(result)
"}

