def count_good_pairs(l, r, x, y):
    """Count the number of good pairs (a, b) such that GCD(a, b) = x and LCM(a, b) = y"""
    if y % x != 0:
        return 0

    k = y // x
    count = 0

    # Find all factor pairs (a', b') of k such that GCD(a', b') = 1
    for i in range(1, int(k**0.5) + 1):
        if k % i == 0:
            j = k // i

            # Check if GCD(i, j) = 1
            if math.gcd(i, j) == 1:
                # Check if x*i and x*j are within [l, r]
                if l <= x * i <= r and l <= x * j <= r:
                    # Count both (i, j) and (j, i) unless i == j
                    if i == j:
                        count += 1
                    else:
                        count += 2

    return count

def solve():
    l, r, x, y = map(int, input().split())
    print(count_good_pairs(l, r, x, y))

if __name__ == "__main__":
    solve()
