    for _ in range(t):
        a, b = map(int, input().split())
        if a == b:
            print(0)
            continue

        # Find the minimum k such that we can make a and b equal
        # We need to find k such that we can form the difference using some subset of {1, 2, ..., k}
        # The total sum of operations is S = k*(k+1)/2
        # We need to split S between a and b such that a + x = b + (S - x)
        # This gives: 2x = b - a + S
        # So x = (S + (b - a)) / 2

        # We need to find the minimum k such that:
        # 1. S + (b - a) is even
        # 2. x <= S and x >= 0
        # 3. x can be formed as a subset sum of {1, 2, ..., k}

        diff = abs(a - b)
        k = 0
        while True:
            k += 1
            S = k * (k + 1) // 2
            if (S + diff) % 2 == 0:
                x = (S + diff) // 2
                if x <= S and x >= 0:
                    # Check if x can be formed as a subset sum of {1, 2, ..., k}
                    # This is always possible if x <= S and x >= 0
                    print(k)
                    break

