import sys

def sum_of_digits(x):
    """Calculate the sum of digits of x"""
    return sum(int(d) for d in str(x))

def solve(n):
    """Find all x such that x + sum_of_digits(x) = n"""
    results = []

    # Iterate over possible x values
    # x must be at least 1 and at most n-1
    # The maximum sum of digits for a number less than n is when it's all 9s
    # For example, if n has d digits, the maximum sum is 9 * d
    # So we can safely check from max(1, n - 100) to n - 1

    for x in range(max(1, n - 100), n):
        if x + sum_of_digits(x) == n:
            results.append(x)

    return results

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    results = solve(n)

    print(len(results))
    for x in results:
        print(x)

if __name__ == "__main__":
    main()
"}

