def count_substrings(s):
    """Count occurrences of each lucky substring."""
    n = len(s)
    count = {}

    # Check all substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substr = s[i:j]
            if substr[0] != '0' and all(c in {'4', '7'} for c in substr):
                count[substr] = count.get(substr, 0) + 1

    return count

def find_lucky_substring(s):
    """Find the lucky substring with maximum occurrences, lexicographically smallest."""
    count = count_substrings(s)

    if not count:
        return -1

    # Find maximum frequency
    max_freq = max(count.values())

    # Find all substrings with maximum frequency
    candidates = [k for k, v in count.items() if v == max_freq]

    # Return lexicographically smallest
    return min(candidates)

# Read input
s = input().strip()

# Find and print result
result = find_lucky_substring(s)
print(result if result != -1 else -1)
"}

