    n = int(sys.stdin.readline())

    # Calculate maximum number of edges
    if n % 2 == 0:
        m = n * n // 4
        set1_size = n // 2
        set2_size = n // 2
    else:
        m = (n * n) // 4
        set1_size = (n - 1) // 2
        set2_size = (n + 1) // 2

    # Construct the graph
    # Set 1: cities 1 to set1_size
    # Set 2: cities set1_size + 1 to n

    print(m)
    for i in range(1, set1_size + 1):
        for j in range(set1_size + 1, n + 1):
            print(f"{i} {j}")

if __name__ == "__main__":
