import sys

def solve():
    n = int(sys.stdin.readline())

    # For odd n, we need to be careful
    # We need to create a complete bipartite graph
    # where one set has floor(n/2) and the other has ceil(n/2)

    if n % 2 == 0:
        set1_size = n // 2
        set2_size = n // 2
    else:
        set1_size = n // 2
        set2_size = n - set1_size

    print(set1_size * set2_size)

    # Construct the graph
    for i in range(1, set1_size + 1):
        for j in range(set1_size + 1, n + 1):
            print(f"{i} {j}")

if __name__ == "__main__":
    solve()
