def is_lucky(s):
    """Check if a string is lucky"""
    last_pos = {}
    for i, ch in enumerate(s):
        if ch not in last_pos:
            last_pos[ch] = [i]
        else:
            last_pos[ch].append(i)

    # Check each character's positions
    for ch, positions in last_pos.items():
        if len(positions) < 2:
