    result = []
    last_used = {}  # last_used[char] = last position used

    for pos in range(n):
        # Try to use the smallest possible character
        for ch in range(ord('a'), ord('z') + 1):
            ch_char = chr(ch)
            # Check if we can use this character at position pos
            if ch_char not in last_used:
                # Character hasn't been used yet
                result.append(ch_char)
                last_used[ch_char] = pos
                break
            else:
