import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Read the grid
    grid = []
    idx = 2
    for i in range(n):
        row = data[idx:idx+m]
        grid.append(row)
        idx += m

    # Find connected components of empty cells
    component_id = [[-1 for _ in range(m)] for _ in range(n)]
    current_id = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and component_id[i][j] == -1:
                # BFS to find the entire component
                queue = [(i, j)]
                component_id[i][j] = current_id
                size = 0

                while queue:
                    x, y = queue.pop(0)
                    size += 1

                    # Check all 4 directions
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < n and 0 <= ny < m:
                            if grid[nx][ny] == '.' and component_id[nx][ny] == -1:
                                component_id[nx][ny] = current_id
                                queue.append((nx, ny))

                current_id += 1

    # Get the size of each component
    component_size = [0] * current_id
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                component_size[component_id[i][j]] += 1

    # Build the result
    result = [['.' for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '*':
                # Check all 4 neighbors
                neighbors = set()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = i + dx, j + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if grid[nx][ny] == '.':
                            neighbors.add(component_id[nx][ny])

                # Sum the sizes of all neighboring components
                total = 0
                for cid in neighbors:
                    total += component_size[cid]

                # The new cell itself is also part of the component
                result[i][j] = str((total + 1) % 10)

    # Print the result
    for row in result:
        print(''.join(row))

if __name__ == '__main__':
    solve()
