import sys

def has_cycle(graph, n):
    """Check if the directed subgraph has a cycle"""
    visited = [False] * (n + 1)
    recursion_stack = [False] * (n + 1)

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            recursion_stack[node] = True

            for neighbor in graph[node]:
                if not visited[neighbor]:
                    if dfs(neighbor):
                        return True
                elif recursion_stack[neighbor]:
                    return True

            recursion_stack[node] = False
            return False

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i):
                return True
    return False

def topological_sort(graph, n):
    """Perform topological sort on the directed subgraph"""
    visited = [False] * (n + 1)
    order = []

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[node]:
                dfs(neighbor)
            order.append(node)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # Reverse to get topological order
    return order[::-1]

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        # Build graph
        directed_graph = [[] for _ in range(n + 1)]
        undirected_edges = []

        for _ in range(m):
            t_i = int(next(it))
            x = int(next(it))
            y = int(next(it))

            if t_i == 1:
                directed_graph[x].append(y)
            else:
                undirected_edges.append((x, y))

        # Check for cycle in directed subgraph
        if has_cycle(directed_graph, n):
            print("NO")
        else:
            print("YES")

            # Get topological order
            topo_order = topological_sort(directed_graph, n)
            topo_map = {node: idx for idx, node in enumerate(topo_order)}

            # Direct undirected edges
            for x, y in undirected_edges:
                if topo_map[x] < topo_map[y]:
                    print(f"{x} {y}")
                else:
                    print(f"{y} {x}")

