                        return True
                elif recursion_stack[neighbor]:
                    return True

            recursion_stack[node] = False
            return False

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i):
                return True
    return False

def topological_sort(graph, n):
    """Perform topological sort on the directed subgraph"""
    visited = [False] * (n + 1)
    order = []

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[node]:
                dfs(neighbor)
            order.append(node)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i)

    # Reverse to get topological order
    return order[::-1]

