    from collections import deque

    # State: (marble1_pos, marble2_pos)
    # We need to reach (positions1[-1], positions2[-1])

    visited = set()
    queue = deque()

    # Start: both marbles at (0, 0)
    start = ((0, 0), (0, 0))
