import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Group students by subject
    subjects = {}
    for _ in range(n):
        s = int(next(it))
        r = int(next(it))
        if s not in subjects:
            subjects[s] = []
        subjects[s].append(r)

    # Sort each subject's skill levels in descending order
    for s in subjects:
        subjects[s].sort(reverse=True)

    # Compute prefix sums for each subject
    prefix_sums = {}
    for s in subjects:
        prefix_sums[s] = [0]
        for i in range(len(subjects[s])):
            prefix_sums[s].append(prefix_sums[s][-1] + subjects[s][i])

    # Find the maximum possible k
    max_k = 0
    for s in subjects:
        if len(subjects[s]) > max_k:
            max_k = len(subjects[s])

    # Try all possible values of k
    max_total = 0
    for k in range(1, max_k + 1):
        total = 0
        for s in subjects:
            if len(subjects[s]) >= k:
                total += prefix_sums[s][k]

        if total > max_total:
            max_total = total

    print(max_total if max_total > 0 else 0)

if __name__ == "__main__":
