import sys

def is_in_check(n, king_x, king_y, pieces):
    # Check if king is in check
    for piece in pieces:
        piece_type, piece_x, piece_y = piece

        # Check if piece can attack king
        if piece_type == 'R' or piece_type == 'Q':
            # Rook or Queen - check row or column
            if abs(piece_x - king_x) == 0:
                # Same row, check if any piece between them
                blocked = False
                for other in pieces:
                    if other == piece:
                        continue
                    other_type, other_x, other_y = other
                    if other_y == king_y and other_x != king_x and other_x != piece_x:
                        if min(piece_x, king_x) < other_x < max(piece_x, king_x):
                            blocked = True
                            break
                if not blocked:
                    return True
            elif abs(piece_y - king_y) == 0:
                # Same column, check if any piece between them
                blocked = False
                for other in pieces:
                    if other == piece:
                        continue
                    other_type, other_x, other_y = other
                    if other_x == king_x and other_y != king_y and other_y != piece_y:
                        if min(piece_y, king_y) < other_y < max(piece_y, king_y):
                            blocked = True
                            break
                if not blocked:
                    return True

        if piece_type == 'B' or piece_type == 'Q':
            # Bishop or Queen - check diagonal
            if abs(piece_x - king_x) == abs(piece_y - king_y):
