def is_alternating(a, b, start_with_a):
    """Check if alternating is possible starting with a or b."""
    if start_with_a:
        # a[0], b[0], a[1], b[1], ...
        for i in range(len(b)):
            if a[i] == b[i]:
                return False
            if i > 0 and a[i] == b[i-1]:
                return False
    else:
        # b[0], a[0], b[1], a[1], ...
        for i in range(len(a)):
            if b[i] == a[i]:
                return False
            if i > 0 and b[i] == a[i-1]:
                return False
    return True

def count_valid_sequences(a, b):
    """Count valid merging sequences for substrings a and b."""
    n = len(a)
    m = len(b)

    # Can't have chaotic merge if length < 2
    if n + m < 2:
        return 0

    # Check if alternating is possible
    start_with_a_possible = is_alternating(a, b, True)
    start_with_b_possible = is_alternating(a, b, False)

    # Count valid sequences
    count = 0
    if start_with_a_possible:
        count += 1
    if start_with_b_possible:
        count += 1

    return count

def solve():
    x = input().strip()
    y = input().strip()

    total = 0

    # Try all substrings of x
    for l1 in range(len(x)):
        for r1 in range(l1, len(x)):
            # Try all substrings of y
            for l2 in range(len(y)):
                for r2 in range(l2, len(y)):
                    a = x[l1:r1+1]
                    b = y[l2:r2+1]

                    total += count_valid_sequences(a, b)
                    total %= MOD

    print(total)

solve()
