def find_min_jumps(x):
    n = 1
    while True:
        # Maximum position with n jumps
        max_pos = n * (n + 1) // 2
        # Try adding all jumps and see if we can subtract enough
        # to get x
        if max_pos >= x:
            # We need to subtract 1 for max_pos - x jumps
            # But we can only subtract 1 for at most n jumps
            if (max_pos - x) <= n:
                return n
        n += 1

