def find_min_jumps(x):
    # Brute force approach
    for n in range(1, 1000):
        # Try all possible combinations of k added values
        for k in range(0, n + 1):
            # Find if there exists a subset of k distinct integers from 1..n that sum to x + n - k
            # This is equivalent to: sum of subset = x + n - k
            # And we need to check if such a subset exists
            target = x + n - k
            if target >= k:
                # We need to find if we can select k distinct integers from 1..n that sum to target
                # And also we have at least k distinct integers (i.e., k <= n)
                if k <= n:
                    # Check if we can select k distinct integers from 1..n that sum to target
                    # And we have enough distinct integers (since we have n, we can choose k)
                    return n
    return -1

t = int(input())
