def get_divisors(n):
    """Return a list of all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    idx = 1

    for i in range(n):
        xi = int(data[idx])
        yi = int(data[idx + 1])
        idx += 2

        # Get all divisors of xi
        divisors = get_divisors(xi)

        # Check which divisors do NOT divide any number in [xi-yi, xi-1]
        valid_divisors = 0

        for d in divisors:
            # Check if d divides any number in the range
            divides_any = False
            for num in range(xi - yi, xi):
                if num % d == 0:
                    divides_any = True
                    break

            if not divides_any:
                valid_divisors += 1

        print(valid_divisors)

if __name__ == "__main__":
    solve()

