def longest_non_decreasing_subsequence(arr):
    """Find the length of the longest non-decreasing subsequence using DP."""
    n = len(arr)
    dp = [1] * n  # dp[i] is the length of longest non-decreasing subsequence ending at i

    for i in range(n):
        for j in range(i):
            if arr[j] <= arr[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

# Read input
n = int(input())
a = list(map(int, input().split()))

# Try all possible subarray reversals
max_length = 0
for l in range(n):
    for r in range(l, n):
        # Reverse subarray [l, r]
        b = a[:l] + a[l:r+1][::-1] + a[r+1:]

        # Find longest non-decreasing subsequence
        length = longest_non_decreasing_subsequence(b)

        # Update maximum
        if length > max_length:
            max_length = length

print(max_length)
"}

