n, m, k = map(int, input().split())

# Traverse row by row, left to right
tubes = []
used = [[False for _ in range(m)] for _ in range(n)]

for i in range(n):
    for j in range(m):
        if not used[i][j]:
            # Start a new tube
            tube = [(i, j)]
            used[i][j] = True

            # If we've created k tubes, just complete the current tube
            if len(tubes) == k:
                while len(tube) < n * m:
                    # Find the next available cell adjacent to the last cell in the tube
                    last_i, last_j = tube[-1]
                    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ni, nj = last_i + di, last_j + dj
                        if 0 <= ni < n and 0 <= nj < m and not used[ni][nj]:
                            tube.append((ni, nj))
                            used[ni][nj] = True
                            break
            else:
                # Continue building the tube
                while len(tube) < n * m:
                    # Find the next available cell adjacent to the last cell in the tube
                    last_i, last_j = tube[-1]
                    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        ni, nj = last_i + di, last_j + dj
                        if 0 <= ni < n and 0 <= nj < m and not used[ni][nj]:
                            tube.append((ni, nj))
                            used[ni][nj] = True
                            break
                tubes.append(tube)

# Output the tubes
for tube in tubes:
    print(len(tube), end=' ')
    for i, j in tube:
        print(i + 1, j + 1, end=' ')
    print()
