tubes = []
used = [[False for _ in range(m)] for _ in range(n)]

tube_count = 0

# Traverse the grid in a specific pattern
for i in range(n):
    if i == 0:
        # For the first row, assign leftmost cells to the first (k-1) tubes
        for j in range(m):
            if not used[i][j]:
                tube_count += 1

                # Create a new tube with the current cell
                tube = [(i, j)]
                used[i][j] = True

                # If we've filled all k tubes, continue
                if tube_count == k:
                    break
        # Continue with the remaining cells
        for j in range(m):
            if not used[0][j]:
                tubes[0].append((0, j))
                used[0][j] = True

    elif i == 1:
        # For the second row, take the last cell of the first (k) columns
        for j in range(k):
            if not used[1][j]:
                tubes.append([(1, j)])
                used[1][j] = True

    # For subsequent rows, fill in the remaining cells
    for j in range(k):
        if not used[i][j]:
            # Start a new tube
            tubes.append([(i, j)])
            used[i][j] = True

            # Fill the rest of the tube
            while True:
                last_i, last_j = tubes[-1][-1]
                found = False
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = last_i + di, last_j + dj
                    if 0 <= ni < n and 0 <= nj < n:  # Actually 0 <= nj < m
                        if not used[ni][nj]:
                            found = True
                            tubes[-1].append((ni, nj))
                            used[ni][nj] = True
                            break
                if not found:
                    break

# Output the tubes
for tube in tubes:
    print(len(tube), end=' ')
    for i, j in tube:
        print(i + 1, j + 1, end=' ')
    print()
