def has_cycle_and_topo_sort(n, adj):
    """Check if there's a cycle and return topological sort if no cycle"""
    visited = [False] * (n + 1)
    rec_stack = [False] * (n + 1)
    topo_order = []

    def dfs(v):
        if rec_stack[v]:
            return False  # Cycle detected
        if visited[v]:
            return True

        visited[v] = True
        rec_stack[v] = True

        for neighbor in adj[v]:
            if not dfs(neighbor):
                return False

        topo_order.append(v)
        rec_stack[v] = False
        return True

    for v in range(1, n + 1):
        if not visited[v]:
            if not dfs(v):
                return None  # Cycle detected

