    substrings_y = []
    for l in range(len(y)):
        for r in range(l, len(y)):
            substrings_y.append((l, r))

    # Count valid merges for each pair of substrings
    total = 0

    for (l1, r1) in substrings_x:
        for (l2, r2) in substrings_y:
            # Extract substrings
            x_sub = x[l1:r1+1]
            y_sub = y[l2:r2+1]

            # DP table: dp[i][j][c] = number of ways to merge first i of x_sub and first j of y_sub with last character c
            # We'll use a dictionary to track counts by last character
            dp = [{} for _ in range(len(x_sub) + 1)]
            dp[0][None] = 1

            for i in range(len(x_sub) + 1):
                for j in range(len(y_sub) + 1):
                    # If we add x_sub[i-1] to the result
                    if i > 0:
                        last_char = x_sub[i-1]
                        # Sum of all states where last character is not last_char
                        sum_prev = 0
                        for c, count in dp[i-1].items():
                            if c != last_char:
                                sum_prev = (sum_prev + count) % MOD
                        dp[i][last_char] = (dp[i].get(last_char, 0) + sum_prev) % MOD

                    # If we add y_sub[j-1] to the result
                    if j > 0:
