def solve():
    n = int(input())
    p = list(map(int, input().split()))

    # Find local minima
    local_minima = []
    for i in range(n):
        left = i - 1 >= 0 and p[i - 1] > p[i]  # Left neighbor has larger value
        right = i + 1 < n and p[i + 1] > p[i]  # Right neighbor has larger value
        if not left and not right:
            local_minima.append(i)

    # For each position x, check if there's a local minimum reachable
    ans = 0
    for x in range(n):
        # Qingshan's component: positions with smaller values than p[x]
        q_set = {i for i in range(n) if p[i] < p[x]}

        # Check if any local minimum is reachable
        found = False
        for m in local_minima:
            if m in q_set:
                # Check if Qingshan can reach m by only moving to smaller values
                # Actually, she just needs to reach m
                q_dist = abs(x - m)

                # Check if Daniel can block
                # Daniel's distance to m: minimal steps from any y != x to m, moving only to larger values
                min_d_dist = float('inf')
                for y in range(n):
                    if y == x:
                        continue
                    # Distance from y to m, moving only to larger values
                    d_dist = abs(y - m)
                    if d_dist < min_d_dist:
                        min_d_dist = d_dist

                # Qingshan moves first
                if q_dist < min_d_dist:
                    found = True
                    break

        if found:
            ans += 1

    print(ans)

