import sys

def solve():
    n, t = map(int, sys.stdin.read().split())

    # Check if it's impossible
    if n == 1 and t == 10:
        print(-1)
        return

    # Smallest n-digit number
    min_num = 10 ** (n - 1)

    # Find the smallest number >= min_num divisible by t
    if min_num % t == 0:
        result = min_num
    else:
        result = min_num + (t - min_num % t)

    # Check if result is an n-digit number
    if result <= 10 ** n - 1:
        print(result)
    else:
        print(-1)

if __name__ == "__main__":
    solve()
