from collections import Counter

def solve():
    s = input().strip()
    t = input().strip()

    # Count characters in s
    count = Counter(s)

    # Try to find the smallest permutation of s that is greater than t
    # We'll try to build the result character by character

    result = []
    i = 0

    while i < len(t) and i < len(s) and count:
        # Find the smallest character in count that is greater than t[i]
        candidate = None
        for char in sorted(count.keys()):
            if char > t[i]:
                candidate = char
                break

        if candidate is not None:
            # Use this character
            result.append(candidate)
            count[candidate] -= 1
            if count[candidate] == 0:
                del count[candidate]
            i += 1
        else:
            # No character greater than t[i], try to find a character equal to t[i]
            candidate = None
            for char in sorted(count.keys()):
                if char == t[i]:
                    candidate = char
                    break

            if candidate is not None:
                # Use this character
                result.append(candidate)
                count[candidate] -= 1
                if count[candidate] == 0:
                    del count[candidate]
                i += 1
            else:
                # No character matches t[i], we can't make it greater by matching prefix
                # We need to find the smallest character greater than t[i] and use it
                candidate = None
                for char in sorted(count.keys()):
                    if char > t[i]:
                        candidate = char
                        break

                if candidate is not None:
                    # Use this character
                    result.append(candidate)
                    count[candidate] -= 1
                    if count[candidate] == 0:
                        del count[candidate]
                    i += 1
                else:
                    # No character greater than t[i] and no character equal to t[i]
                    return -1

    # After matching the prefix, we have remaining characters in count
    # Add them in sorted order to get the smallest possible suffix
    if i < len(s):
        # We have remaining characters, add them in sorted order
        result.extend(sorted(count.keys()))

    # Check if the result is greater than t
    result_str = ''.join(result)
    if result_str > t:
        return result_str
    else:
        return -1

