def get_suffix(line, k):
    """Get the suffix starting from the k-th vowel from the end"""
    vowels = {'a', 'e', 'i', 'o', 'u'}
    vowels_pos = []

    # Find all vowel positions
    for i, char in enumerate(line):
        if char in vowels:
            vowels_pos.append(i)

    # If not enough vowels, can't rhyme
    if len(vowels_pos) < k:
        return None

    # Get the position of the k-th vowel from the end
    kth_vowel_pos = vowels_pos[-k]

    # Return the suffix starting from that position
    return line[kth_vowel_pos:]

