    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    n = int(data[0])
    queries = []
    idx = 1

    for i in range(n):
        xi = int(data[idx])
        yi = int(data[idx + 1])
        queries.append((xi, yi))
        idx += 2

    # Precompute divisors for all numbers up to 100000
    max_num = 100000
    divisors = [[] for _ in range(max_num + 1)]

    for i in range(1, max_num + 1):
        for j in range(i, max_num + 1, i):
            divisors[j].append(i)

    # Process queries
    results = []
    for i in range(n):
