import sys

def is_valid_word(word):
    # Check if word is a valid Petya's language word
    if word.endswith("lios"):
        return "adjective", "masculine"
    if word.endswith("liala"):
        return "adjective", "feminine"
    if word.endswith("etr"):
        return "noun", "masculine"
    if word.endswith("etra"):
        return "noun", "feminine"
    if word.endswith("initis"):
        return "verb", "masculine"
    if word.endswith("inites"):
        return "verb", "feminine"
    return None, None

def solve():
    input_text = sys.stdin.read().strip()
    words = input_text.split()

    # Check if all words are valid
    for word in words:
        part_of_speech, gender = is_valid_word(word)
        if part_of_speech is None:
            print("NO")
            return

    # If only one word, it's a valid sentence
    if len(words) == 1:
        print("YES")
        return

    # Check if it's a valid statement
    # Get part of speech and gender for each word
    pos_list = []
    gender_list = []
    for word in words:
        part_of_speech, gender = is_valid_word(word)
        pos_list.append(part_of_speech)
        gender_list.append(gender)

    # Check gender consistency
    if len(set(gender_list)) > 1:
        print("NO")
        return

    # Check part of speech order: adjectives (0+) + noun (1) + verbs (0+)
    # Find the index of the noun
    noun_index = -1
    for i, pos in enumerate(pos_list):
        if pos == "noun":
            noun_index = i
            break

    if noun_index == -1:
        # No noun found
        print("NO")
        return

    # Check all words before noun are adjectives
    for i in range(noun_index):
        if pos_list[i] != "adjective":
            print("NO")
            return

    # Check all words after noun are verbs
    for i in range(noun_index + 1, len(pos_list)):
        if pos_list[i] != "verb":
            print("NO")
            return

    print("YES")

if __name__ == "__main__":
    solve()
"}

