import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    d = int(data[1])
    points = list(map(int, data[2:2+n]))

    points.sort()

    min_remove = n  # Worst case: remove all but one

    for i in range(n):
        # Find the farthest point such that points[j] - points[i] <= d
        low, high = i, n - 1
        while low <= high:
            mid = (low + high) // 2
            if points[mid] - points[i] <= d:
                low = mid + 1
            else:
                high = mid - 1

        # high is the farthest valid index
        window_size = high - i + 1
        remove = n - window_size

        if remove < min_remove:
            min_remove = remove

    print(min_remove)

if __name__ == "__main__":
    solve()
"}

